import * as THREE from './vendor/three.module.js';
// Visual terrain estimate from reference aerials; not surveyed elevations.
export function createTerrain(boundary,extensions=[]){
 const group=new THREE.Group(),inside=(x,z)=>[boundary,...extensions].some(poly=>{let v=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>z)!==(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])v=!v;}return v;});
 const distance=(x,z)=>{let best=1e9;for(let i=0;i<boundary.length;i++){const a=boundary[i],b=boundary[(i+1)%boundary.length],dx=b[0]-a[0],dz=b[1]-a[1],t=THREE.MathUtils.clamp(((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz),0,1);best=Math.min(best,Math.hypot(x-a[0]-t*dx,z-a[1]-t*dz));}return best;};
 const gauss=(x,z,a,b,c,d)=>Math.exp(-(((x-a)/c)**2+((z-b)/d)**2));
 const height=(x,z)=>{if(inside(x,z))return 5.7;const d=distance(x,z),blend=1-Math.exp(-d/32),ridge=122*gauss(x,z,-225,-222,250,138)+133*gauss(x,z,125,-337,275,185)+95*gauss(x,z,420,-290,250,220),front=THREE.MathUtils.smoothstep(z,10,220)*34,ripple=Math.sin(x*.022+z*.009)*Math.sin(z*.028)*4.3,fade=1-THREE.MathUtils.smoothstep(Math.max(Math.abs(x)/850,Math.abs(z+130)/660),.77,1);return (5.7+blend*(ridge-front+ripple))*fade-16*(1-fade);};
 const pos=[],idx=[],NX=155,NZ=120;for(let j=0;j<=NZ;j++)for(let i=0;i<=NX;i++){const x=-850+i/NX*1700,z=-790+j/NZ*1320;pos.push(x,height(x,z),z);}for(let j=0;j<NZ;j++)for(let i=0;i<NX;i++){const k=j*(NX+1)+i;idx.push(k,k+NX+1,k+1,k+1,k+NX+1,k+NX+2);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setIndex(idx);g.computeVertexNormals();const ground=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:'#789164',roughness:1}));ground.receiveShadow=true;group.add(ground);
 let seed=613;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};const trees=[[],[],[]];for(let i=0;i<4500;i++){const x=-690+rand()*1390,z=-620+rand()*970;if(inside(x,z)||distance(x,z)<8)continue;const y=height(x,z);if(y<0||rand()>.65)continue;const h=5+rand()*9,r=3+rand()*3.4;trees[i%3].push([x,y+h*.58,z,r,h*.64,r]);}const m4=new THREE.Matrix4(),q=new THREE.Quaternion(),p=new THREE.Vector3(),s=new THREE.Vector3();['#496d4d','#557c51','#64875a'].forEach((color,k)=>{const m=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,1),new THREE.MeshStandardMaterial({color,roughness:1}),trees[k].length);trees[k].forEach((t,i)=>{p.set(t[0],t[1],t[2]);s.set(t[3],t[4],t[5]);m4.compose(p,q,s);m.setMatrixAt(i,m4);});m.receiveShadow=true;group.add(m);});return group;
}
